FALACIAS = {
 'Apelo à natureza': ('Appeal to nature', '"It\'s natural, so it\'s good"'),
 'Lei de Hume (do é ao deve)': ("Hume's law (from is to ought)", 'Deriving a norm from a fact'),
 'Apelo à tradição': ('Appeal to tradition', '"It\'s always been this way"'),
 'Apelo à multidão e à normalidade': ('Appeal to popularity and normality', '"Everybody does it"'),
 'Apelo à autoridade': ('Appeal to authority', '"So-and-so said it or did it"'),
 'Critério arbitrário (especismo)': ('Arbitrary criterion (speciesism)', 'An irrelevant trait chosen as the moral boundary'),
 'Definição persuasiva': ('Persuasive definition', 'Defining the term to win the argument'),
 'Petição de princípio': ('Begging the question', 'The conclusion is hidden in the premise'),
 'Falácia do contínuo': ('Continuum fallacy', 'No exact line means no difference'),
 'Generalização do acidente': ('Hasty generalization from an exception', 'An exception used as the rule'),
 'Falsa dicotomia': ('False dichotomy', 'Either this or that, with no third way'),
 'Falácia do nirvana': ('Nirvana fallacy', "If it isn't perfect, it doesn't count"),
 'Tu quoque': ('Tu quoque', '"You do it too"'),
 'Ad hominem e envenenamento do poço': ('Ad hominem and poisoning the well', 'Attacking the person'),
 'Culpa por associação': ('Guilt by association', 'Linking the idea to something hated'),
 'Falácia da prioridade': ('Priority fallacy', '"There are more important things"'),
 'Evidência anedótica': ('Anecdotal evidence', 'One case against the data'),
 'Cherry picking': ('Cherry picking', 'Selecting only the favorable data'),
 'Falso meio-termo': ('False middle ground', 'The truth is always in the middle'),
 'Mudança de questão (red herring)': ('Changing the question (red herring)', 'Swapping "is it wrong?" for another question'),
}

VIESES = {
 'Dissonância cognitiva (paradoxo da carne)': ('Cognitive dissonance (the meat paradox)', 'Loving animals and eating them creates tension, resolved by denying minds to the animals eaten (Bastian et al., 2012)'),
 'Raciocínio motivado': ('Motivated reasoning', 'Looking for reasons for the conclusion you already want'),
 'Viés de confirmação': ('Confirmation bias', 'Accepting only what confirms a prior belief'),
 'Viés do status quo': ('Status quo bias', 'Preferring the current state because it is current'),
 'Justificação do sistema': ('System justification', 'Legitimizing the existing order to reduce discomfort'),
 'Ignorância deliberada': ('Willful ignorance', 'Avoiding information that would create an obligation'),
 'Categorização funcional': ('Functional categorization', '"Food" animals are granted less mind than "pet" animals'),
 'Viés de grupo (ingroup)': ('Ingroup bias', 'Valuing "our own" and devaluing outsiders'),
 'Insensibilidade à escala': ('Scope insensitivity', "Billions of victims don't weigh more than one"),
 'Difusão de responsabilidade': ('Diffusion of responsibility', 'Shared blame feels like no blame'),
 'Reatância psicológica': ('Psychological reactance', 'Pushing back when freedom feels threatened'),
 'Cognição protetora da identidade': ('Identity-protective cognition', 'Rejecting ideas that threaten the group or one\'s identity'),
 'Heurística do afeto': ('Affect heuristic', '"I like it, so it\'s good"'),
 'Licença moral': ('Moral licensing', 'One good act licenses a bad one'),
 'Viés de otimismo e excepcionalismo': ('Optimism bias and exceptionalism', '"My meat is different"'),
 'Viés de sobrevivência': ('Survivorship bias', 'We only see those who made it'),
 'Racionalização pelos 4Ns': ('The 4Ns rationalization', 'Justifying eating animals by saying it is natural, normal, necessary and nice (Piazza and colleagues, 2015).'),
 'Busca de hipocrisia': ('Hypocrisy hunting', 'Looking for an inconsistency in whoever defends an idea so as not to examine the idea.'),
 'Negação de mente': ('Mind denial', 'Attributing less mind and less capacity to suffer to the animals we eat.'),
 'Depreciação de quem faz o bem': ('Do-gooder derogation', 'Belittling people who act for moral reasons, because their conduct feels like an accusation.'),
 'Desvalorização reativa': ('Reactive devaluation', 'Rejecting a proposal because it came from the other side.'),
 'Efeito do mensageiro': ('Messenger effect', 'Judging the message by who says it rather than by what it says.'),
 'Efeito manada e conformidade social': ('Bandwagon effect and social conformity', 'Adopting a habit or an idea because many people around you do.'),
 'Ignorância pluralista': ('Pluralistic ignorance', 'Many disagree in private but think everyone else agrees.'),
 'Efeito do padrão': ('Default effect', 'Sticking with the option that comes ready-made, like the plate with meat.'),
 'Efeito da verdade ilusória e da mera exposição': ('Illusory truth and mere exposure effects', 'What you hear often seems true, and what is familiar seems better.'),
 'Viés de omissão e viés do perpetrador': ('Omission bias and perpetrator bias', "Judging as less serious the harm we don't cause with our own hands, or that results from not acting."),
 'Viés teleológico e detecção de agente': ('Teleological bias and agency detection', 'Seeing purpose and intention in nature: animals would "exist for" something.'),
 'Desaparecimento da compaixão': ('Collapse of compassion', 'The more victims, the less we feel for each; one identifiable victim moves us more than millions.'),
 'Aversão à perda e efeito dotação': ('Loss aversion and the endowment effect', 'Losing what you have weighs more than gaining something equivalent.'),
 'Custo irrecuperável e justificação do esforço': ('Sunk cost and effort justification', "Carrying on because you've invested a lot, not because it's worth it."),
 'Retrospecção rosada': ('Rosy retrospection', 'Remembering the past as better than it was.'),
 'Excesso de confiança (Dunning-Kruger)': ('Overconfidence (Dunning-Kruger)', 'People who know little about a topic tend to overestimate what they know.'),
 'Realismo ingênuo e ponto cego do viés': ('Naive realism and the bias blind spot', 'Thinking we see the world as it is and only others are biased.'),
 'Pensamento antropocêntrico': ('Anthropocentric thinking', 'Using humans as the measure of everything, including of what counts as feeling.'),
 'Viés do natural': ('Naturalness bias', 'What seems natural is judged better and safer.'),
 'Viés de disponibilidade': ('Availability bias', "Judging by the easiest memory, like an acquaintance's case, rather than by the data."),
 'Viés de autoridade': ('Authority bias', 'Accepting a claim because of the prestige of whoever makes it.'),
 'Viés do presente': ('Present bias', 'Giving too much weight to now and too little to future consequences.'),
 'Efeito halo': ('Halo effect', 'One good quality, like "local" or "organic", colors the judgment of everything else.'),
 'Orientação à dominância social': ('Social dominance orientation', 'Preferring hierarchies between groups, including between species.'),
 'Essencialismo psicológico': ('Psychological essentialism', 'Believing each kind of being has a fixed essence that defines its place.'),
 'Masculinidade e carne': ('Masculinity and meat', 'Associating eating meat with manliness, which makes change feel like a threat to identity.'),
 'Estereótipo': ('Stereotyping', 'Judging someone by a simplified image of the group they belong to.'),
 'Dissociação e eufemismo': ('Dissociation and euphemism', 'Separating the animal from the food, including through the words we use.'),
 'Falso consenso': ('False consensus', 'Overestimating how many people think like us.'),
 'Neofobia alimentar': ('Food neophobia', 'Distrusting unfamiliar foods.'),
 'Efeito nocebo': ('Nocebo effect', 'Expecting something to do harm produces real symptoms.'),
 'Viés de saliência': ('Salience bias', 'Giving weight to what grabs attention, like the distance traveled, rather than to what matters most.'),
 'Viés de intenção': ('Intention bias', 'Reacting more strongly to harm when someone caused it on purpose than to equal harm from causes with no one to blame.'),
 'Viés do meio-termo': ('Middle-ground bias', 'Thinking the middle position is always the most sensible.'),
 'Lacuna de empatia': ('Empathy gap', 'Feeling less empathy for an animal the more evolutionarily distant it is from us.'),
 'Tamanhismo': ('Sizeism', 'Giving an animal less importance because it is small.'),
 'Inteligentismo': ('Intelligence bias', 'Giving an animal less importance because it is seen as not very intelligent.'),
 'Substratismo': ('Substratism', 'Giving a being less importance because of the material it is made of, as with non-organic beings.'),
 'Viés de proporção': ('Proportion bias', 'Judging help by the fraction of the problem it solves rather than by the number of individuals helped.'),
 'Hipótese do mundo justo': ('Just-world hypothesis', 'Believing the world is fair, so those who suffer are getting what is due to them.'),
 'Negligência da probabilidade': ('Neglect of probability', 'Deciding under uncertainty without weighing the probability, treating a risk as certain or as nonexistent.'),
 'Efeito de ambiguidade': ('Ambiguity effect', 'Avoiding options whose chance of success is unknown, even when they may be the best ones.'),
 'Viés de avaliabilidade': ('Evaluability bias', 'Giving more weight to what is easy to measure than to what matters most.'),
 'Negligência da duração': ('Duration neglect', 'Judging an experience by its striking moments and its end, without counting how long it lasted.'),
 'Viés pró-inovação': ('Pro-innovation bias', 'Overestimating what an innovation will solve and not seeing its limits.'),
 'Digitalização de crenças': ('Belief digitization', 'Treating a probability as if it were zero or one instead of taking the uncertainty into account.'),
 'Perseverança da crença': ('Belief perseverance', 'Holding on to a belief even after learning of evidence against it.'),
 'Efeito de influência contínua': ('Continued influence effect', 'Information that has already been corrected keeps influencing what a person thinks.'),
 'Viés de soma zero': ('Zero-sum bias', "Seeing a situation as a contest in which one side's gain is the other's loss, even when it is not."),
 'Cascata de disponibilidade': ('Availability cascade', 'An idea gains credit by being repeated a lot in public, and the more credit it gains, the more it is repeated.'),
 'Correlação ilusória': ('Illusory correlation', 'Seeing a link between two things that merely happened together.'),
 'Efeito de enquadramento': ('Framing effect', 'The same information leads to different judgments depending on how it is presented.'),
 'Ilusão de profundidade explicativa': ('Illusion of explanatory depth', 'Thinking you understand how something works much better than you actually do.'),
}

